def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # For every contiguous diagonal run of a non-background color, extend its
    # diagonal backwards from the upper endpoint to the top/side boundary.
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                if (r+dr < h and 0 <= c+dc < w and grid[r+dr][c+dc] == color):
                    # Walk to uppermost endpoint of this diagonal run.
                    rr, cc = r, c
                    while rr-dr >= 0 and 0 <= cc-dc < w and grid[rr-dr][cc-dc] == color:
                        rr, cc = rr-dr, cc-dc
                    key = (color, rr, cc, dr, dc)
                    if key in seen:
                        continue
                    seen.add(key)
                    # Extend in the direction opposite the run's downwards slope.
                    rr -= dr
                    cc -= dc
                    while rr >= 0 and 0 <= cc < w:
                        if out[rr][cc] == bg:
                            out[rr][cc] = color
                        rr -= dr
                        cc -= dc
    return out

